	/** 
	 * jumpstart the process by instantiating2 Interview
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		interviewId = InterviewService.getInterviewInstance()
		.createInterview( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		InterviewService.getInterviewInstance()
				.createInterview( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.interviewSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Interview : " + successValue.getInterviewId());
							  if (successValue.getInterviewId().equals(interviewId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfInterviewList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Interview test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on interview consumed")
					);
			subscriber.interviewSubscribe( interviewId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Interview : " + successValue.getInterviewId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfInterviewList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on interview for interviewId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Interview. 
	 */
	protected Interview read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Interview" );

		Interview entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Interview with primary key" );
		msg.append( interviewId );
		
		InterviewFetchOneSummary fetchOneSummary = new InterviewFetchOneSummary( interviewId );

		try {
			entity = InterviewService.getInterviewInstance().getInterview( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Interview " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Interview.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Interview." );

		StringBuilder msg = new StringBuilder( "Failed to update a Interview : " );        
		Interview entity = read();
		UpdateInterviewCommand command = generateUpdateCommand();
		command.setInterviewId(entity.getInterviewId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Interview." );

			// for use later on...
			interviewId = entity.getInterviewId();

			InterviewService proxy = InterviewService.getInterviewInstance();  

			proxy.updateInterview( command ).get();

			LOGGER.info( "-- Successfully saved Interview - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + interviewId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Interview.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Interview." );

		Interview entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Interview with id " + interviewId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Interview with id " + interviewId );

			throw e;
		}

		try{
			InterviewService.getInterviewInstance().delete( new DeleteInterviewCommand( entity.getInterviewId() ) ).get();
			LOGGER.info( "-- Successfully deleted Interview with id " + interviewId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Interview with id " + interviewId );

			throw e;
		}
	}

	/**
	 * get all Interviews.
	 */
	protected List<Interview> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Interviews:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Interview : " );        
		List<Interview> collection  = new ArrayList<>();

		try {
			// call the static get method on the InterviewService
			collection = InterviewService.getInterviewInstance().getAllInterview();
			assertNotNull( collection, "An Empty collection of Interview was incorrectly returned.");
			
			// Now print out the values
			Interview entity = null;            
			Iterator<Interview> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getInterviewId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

